std::vector<std::pair<std::vector<std::pair<std::array<double, 3>, std::array<double, 3>>>, std::vector<std::pair<std::array<double, 3>, std::array<double, 3>>>>> rays;
for (int i = 0; i < numberOfChecks; ++i) {
    std::array<double, 3> direction = {std::rand() / static_cast<double>(RAND_MAX) - 0.5, std::rand() / static_cast<double>(RAND_MAX) - 0.5, std::rand() / static_cast<double>(RAND_MAX) - 0.5};
    double length = std::sqrt(direction[0] * direction[0] + direction[1] * direction[1] + direction[2] * direction[2]);
    if (length < 1e-10) continue;
    direction[0] /= length; direction[1] /= length; direction[2] /= length;
    std::array<double, 3> origin = {p.x(), p.y(), p.z()};
    std::array<double, 3> endpoint = {origin[0] + 1000.0 * direction[0], origin[1] + 1000.0 * direction[1], origin[2] + 1000.0 * direction[2]};
    std::vector<std::pair<std::array<double, 3>, std::array<double, 3>>> ray = {{origin, endpoint}};
    rays.push_back({ray, {}});
}
int intersections = 0;
for (const auto& ray : rays) {
    std::vector<std::pair<std::array<double, 3>, std::array<double, 3>>> ray_segment = ray.first;
    std::vector<std::pair<std::array<double, 3>, std::array<double, 3>>> intersections_list;
    tree.all_intersected_primitives(ray_segment[0].first, ray_segment[0].second, std::back_inserter(intersections_list));
    intersections += intersections_list.size();
}
return intersections % 2 == 1;

